from pathlib import Path
import json
ROOT=Path(__file__).resolve().parents[1]
data=json.loads((ROOT/'outputs/dashboard_data.json').read_text())
# Dashboard has the complete request-level sample embedded, so it opens without a local-server setup.
template=r'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Operations Analytics | The work behind the wait</title>
<script src="https://cdn.jsdelivr.net/npm/chart.js@4.4.7/dist/chart.umd.min.js"></script>
<style>
:root{--ink:#172f38;--muted:#61747b;--paper:#f3f6f4;--card:#fff;--line:#d8e1df;--teal:#167c80;--coral:#c46d53;--gold:#d5a64b;--blue:#6686b2;--shadow:0 8px 24px rgba(23,47,56,.06)}*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font:15px/1.5 Inter,ui-sans-serif,system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}header{background:#173a46;color:#f7faf8;padding:27px max(22px,calc((100vw - 1260px)/2)) 25px}header .kicker{text-transform:uppercase;letter-spacing:.16em;font-size:11px;color:#b9d7d2;font-weight:700}h1{font-size:clamp(30px,4vw,45px);line-height:1.08;max-width:850px;margin:8px 0 12px;letter-spacing:-.035em}header p{max-width:780px;color:#d8e6e2;margin:0;font-size:16px}.wrap{max-width:1260px;margin:0 auto;padding:24px 22px 50px}.filters{display:grid;grid-template-columns:repeat(6,minmax(120px,1fr));gap:10px;background:#fff;border:1px solid var(--line);padding:15px;border-radius:15px;box-shadow:var(--shadow)}label{display:block;color:var(--muted);font-size:11px;font-weight:700;text-transform:uppercase;letter-spacing:.06em;margin-bottom:5px}select,input{font:inherit;font-size:13px;color:var(--ink);background:#fbfcfb;border:1px solid #ced9d6;border-radius:8px;padding:9px;width:100%}.filter-note{font-size:12px;color:var(--muted);align-self:end;padding-bottom:8px}.story-nav{display:flex;gap:8px;flex-wrap:wrap;margin:22px 0 17px}.story-nav button{border:1px solid var(--line);border-radius:99px;background:#fff;padding:10px 17px;color:var(--ink);font-weight:700;cursor:pointer}.story-nav button.active{background:var(--ink);color:white;border-color:var(--ink)}.chapter{display:none}.chapter.active{display:block}.chapter-intro{display:grid;grid-template-columns:1.2fr 1fr;gap:24px;align-items:end;margin:18px 0}.chapter h2{margin:0 0 6px;font-size:27px;letter-spacing:-.025em}.chapter-intro p{margin:0;color:var(--muted);max-width:710px}.chapter-intro .callout{border-left:3px solid var(--coral);padding:8px 0 8px 13px;color:#42565c;font-size:13px}.kpis{display:grid;grid-template-columns:repeat(5,1fr);gap:12px;margin:16px 0}.kpi{background:var(--card);border:1px solid var(--line);border-radius:14px;padding:15px 16px;box-shadow:var(--shadow)}.kpi span{font-size:11px;color:var(--muted);text-transform:uppercase;letter-spacing:.07em;font-weight:700}.kpi strong{display:block;font-size:28px;letter-spacing:-.035em;margin-top:4px;line-height:1.25}.kpi small{color:var(--muted);display:block;margin-top:3px;font-size:11px}.grid2{display:grid;grid-template-columns:1.1fr .9fr;gap:14px;margin:14px 0}.grid2.equal{grid-template-columns:1fr 1fr}.card{background:var(--card);border:1px solid var(--line);border-radius:15px;padding:18px;box-shadow:var(--shadow);min-width:0}.card h3{margin:0 0 4px;font-size:17px;letter-spacing:-.015em}.sub{color:var(--muted);font-size:12px;margin:0 0 14px}.chartbox{height:300px;position:relative}.chartbox.short{height:230px}.insight{background:#e8f0ed;border-radius:13px;padding:16px 18px;margin:15px 0;color:#294b4c}.insight b{color:#173a46}.tablewrap{overflow:auto;max-height:440px;border:1px solid var(--line);border-radius:9px}table{width:100%;border-collapse:collapse;font-size:12px;white-space:nowrap}th{text-align:left;background:#f0f5f3;color:#486067;position:sticky;top:0;z-index:1;text-transform:uppercase;letter-spacing:.045em;font-size:10px}td,th{padding:10px 11px;border-bottom:1px solid #e5ebe9}tbody tr:hover{background:#f4f8f6}.pill{display:inline-block;border-radius:99px;padding:3px 8px;font-weight:700;font-size:10px;background:#f9e7e1;color:#913f2c}.pill.ok{background:#e4f3ea;color:#256344}.score{font-weight:800;font-variant-numeric:tabular-nums}.scenario{display:grid;grid-template-columns:1fr 1fr;gap:18px}.range-row{margin:16px 0}.range-row input{padding:0;accent-color:var(--teal)}.range-label{display:flex;justify-content:space-between;align-items:center;font-size:13px;font-weight:700}.scenario-result{background:#173a46;color:white;border-radius:14px;padding:19px}.scenario-result strong{font-size:35px;display:block;letter-spacing:-.03em}.scenario-result p{font-size:12px;color:#d2e2df;margin:5px 0 0}.footnote{color:var(--muted);font-size:11px;margin:17px 0 0}.footer{border-top:1px solid var(--line);padding-top:17px;margin-top:30px;color:var(--muted);font-size:12px}.empty{padding:28px;color:var(--muted);text-align:center}@media(max-width:900px){.filters{grid-template-columns:repeat(3,1fr)}.kpis{grid-template-columns:repeat(2,1fr)}.grid2,.grid2.equal,.chapter-intro,.scenario{grid-template-columns:1fr}}@media(max-width:520px){.filters{grid-template-columns:repeat(2,1fr)}.wrap{padding:15px}.kpi strong{font-size:24px}}
</style></head><body>
<header><div class="kicker">Operations field notes · sample data, Jul 2025–Jan 2026</div><h1>The work behind the wait.</h1><p>A service desk can look healthy on an average day and still leave a small but important group of people waiting far too long. Follow the queue, find where it sticks, and test which changes might make the next shift easier.</p></header>
<main class="wrap">
<section class="filters" aria-label="Dashboard filters">
<div><label for="service">Request type</label><select id="service"></select></div><div><label for="team">Team</label><select id="team"></select></div><div><label for="priority">Priority</label><select id="priority"></select></div><div><label for="channel">Intake channel</label><select id="channel"></select></div><div><label for="from">Created from</label><input id="from" type="date" value="2025-07-01"></div><div><label for="to">Created through</label><input id="to" type="date" value="2026-01-14"></div>
</section><p class="filter-note" id="filterNote">Showing all requests in the selected window. Filters update the whole story, including the queue table.</p>
<nav class="story-nav"><button class="active" data-chapter="promise">1 · The promise</button><button data-chapter="stalls">2 · Where work sticks</button><button data-chapter="next">3 · The next shift</button></nav>
<section class="chapter active" id="promise"><div class="chapter-intro"><div><h2>The average is not the whole story</h2><p>Start with the service promise. How many requests met it, how many remain open, and how far apart are the typical wait and the slowest tenth?</p></div><div class="callout"><b>How to read this:</b> resolved cases are measured against their target. Open cases are shown separately; they count as at risk only after their elapsed age passes the target.</div></div>
<div class="kpis" id="kpis"></div><div class="grid2"><article class="card"><h3>Work coming in, work going out</h3><p class="sub">Created requests versus resolved requests, by month of arrival.</p><div class="chartbox"><canvas id="flowChart"></canvas></div></article><article class="card"><h3>Where the SLA promise breaks</h3><p class="sub">Share of requests breached or currently past target, by request type.</p><div class="chartbox"><canvas id="riskChart"></canvas></div></article></div><div class="insight" id="promiseInsight"></div></section>
<section class="chapter" id="stalls"><div class="chapter-intro"><div><h2>Time leaks between teams</h2><p>Some work is slow because it is difficult. Some is slow because it keeps moving. This view looks at both the long tail and the handoffs around it.</p></div><div class="callout"><b>A caution about rankings:</b> this is not a staff scorecard. Harder cases are more likely to be handed off and take longer. Use the patterns to find process friction, then inspect the cases.</div></div>
<div class="grid2"><article class="card"><h3>Median and 90th percentile wait</h3><p class="sub">A gap between these lines means a small group is waiting much longer than most.</p><div class="chartbox"><canvas id="tailChart"></canvas></div></article><article class="card"><h3>Handoffs and resolution time</h3><p class="sub">Resolved cases only. The comparison is descriptive, not proof of cause.</p><div class="chartbox"><canvas id="handoffChart"></canvas></div></article></div><div class="grid2 equal"><article class="card"><h3>Team risk after adjusting for work mix</h3><p class="sub">Observed risk minus expected risk within the same service-type and priority mix.</p><div class="chartbox short"><canvas id="teamChart"></canvas></div></article><article class="card"><h3>Priority by request type</h3><p class="sub">A high-risk cell points to a queue where the service promise may not match the way work is handled.</p><div class="tablewrap" style="max-height:280px"><table id="heatTable"></table></div></article></div><div class="insight" id="stallsInsight"></div></section>
<section class="chapter" id="next"><div class="chapter-intro"><div><h2>Make the next shift more manageable</h2><p>Put aged work first, make ownership visible, and target repeated handoffs. The queue below is ranked by urgency and elapsed time, not by customer value.</p></div><div class="callout"><b>Attention score:</b> a transparent triage aid built from priority, time against target, handoffs, complexity and reopening. It helps order a review; it does not replace judgement.</div></div>
<div class="grid2"><article class="card"><h3>Try a simple operating change</h3><p class="sub">Adjust the assumptions to see the approximate pressure it could remove. This is scenario arithmetic, not a validated forecast.</p><div class="scenario"><div><div class="range-row"><div class="range-label"><span>Reduce avoidable handoffs</span><b id="handoffPct">20%</b></div><input id="handoffSlider" type="range" min="0" max="60" step="5" value="20"></div><div class="range-row"><div class="range-label"><span>Add usable capacity</span><b id="capacityPct">10%</b></div><input id="capacitySlider" type="range" min="0" max="30" step="5" value="10"></div></div><div class="scenario-result"><span style="font-size:11px;text-transform:uppercase;letter-spacing:.08em;color:#c5dcd7">Indicative p90 wait</span><strong id="scenarioHours">--</strong><span id="scenarioDelta">--</span><p>Estimated change against the selected cases, based on stated assumptions. Treat it as a discussion starter.</p></div></div><p class="footnote">Assumption used: each removed handoff reduces the long-tail time multiplicatively; capacity reduces the remaining waiting component. Actual effects depend on staffing, case mix and queue rules.</p></article><article class="card"><h3>First requests to review</h3><p class="sub">Filtered queue, highest attention score first. Use the request ID to find the full record in the data file.</p><div style="margin-bottom:10px"><label for="queueSearch">Search the queue</label><input id="queueSearch" type="search" placeholder="Request ID, team, or request type"></div><div class="tablewrap"><table id="queueTable"><thead><tr><th>ID</th><th>Status</th><th>Priority</th><th>Request type</th><th>Team</th><th>Elapsed</th><th>Target</th><th>Attention</th></tr></thead><tbody></tbody></table></div></article></div><div class="insight" id="nextInsight"></div></section>
<div class="footer">This is an illustrative service operation, not a live service desk. The data is synthetic; SLA targets and the attention score are defined in the project notes. The dashboard uses Chart.js from a CDN, so charts need an internet connection. The filters and tables still explain the analysis structure when the charts are unavailable.</div>
</main>
<script>
const DATA = __DATA__;
const $=id=>document.getElementById(id);let charts={};let currentRows=[];const fmtPct=v=>(100*v).toFixed(1)+'%';const fmtH=v=>v==null||!Number.isFinite(+v)?'—':(+v<48?(+v).toFixed(1)+' h':(+v/24).toFixed(1)+' d');const fmtNum=v=>Number(v).toLocaleString('en-US');
function fill(id,opts){$(id).innerHTML=opts.map(v=>`<option value="${esc(v)}">${esc(v)}</option>`).join('')}
function esc(s){return String(s??'').replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;')}
fill('service',DATA.service_options);fill('team',DATA.team_options);fill('channel',DATA.channel_options);fill('priority',DATA.priority_options);
function filtered(){let a=$('from').value,b=$('to').value;return DATA.rows.filter(r=>( $('service').value==='All'||r.service_type===$('service').value)&&($('team').value==='All'||r.team===$('team').value)&&($('channel').value==='All'||r.channel===$('channel').value)&&($('priority').value==='All'||r.priority===$('priority').value)&&(!a||r.created_at.slice(0,10)>=a)&&(!b||r.created_at.slice(0,10)<=b))}
function quantile(a,q){if(!a.length)return 0;let x=[...a].sort((m,n)=>m-n);return x[Math.min(x.length-1,Math.floor((x.length-1)*q))]}
function avg(a){return a.length?a.reduce((s,v)=>s+v,0)/a.length:0}function pct(a){return a.length?a.filter(Boolean).length/a.length:0}function group(rows,key){let o={};rows.forEach(r=>(o[r[key]]??=[]).push(r));return o}
function destroy(id){if(charts[id]){charts[id].destroy();delete charts[id]}}
const palette=['#167c80','#c46d53','#d5a64b','#6686b2','#779a76','#8d7ba9','#6b8b91','#c08c69'];
function chart(id,type,labels,datasets,opts={}){destroy(id);if(!window.Chart)return;let canvas=$(id);charts[id]=new Chart(canvas,{type,data:{labels,datasets:datasets.map((d,i)=>({...d,backgroundColor:d.backgroundColor||palette[i%palette.length],borderColor:d.borderColor||palette[i%palette.length],borderWidth:d.borderWidth??1,tension:.25,pointRadius:2}))},options:{responsive:true,maintainAspectRatio:false,interaction:{mode:'index',intersect:false},plugins:{legend:{display:datasets.length>1,position:'bottom',labels:{boxWidth:10,font:{size:10}}}},scales:type==='doughnut'?{}:{x:{grid:{display:false},ticks:{font:{size:10}}},y:{beginAtZero:true,grid:{color:'#edf1ef'},ticks:{font:{size:10}}}},...opts}})}
function update(){currentRows=filtered();const all=currentRows,res=all.filter(r=>r.status==='Resolved'),open=all.filter(r=>r.status==='Open'),risk=all.filter(r=>r.sla_breached_or_at_risk),sla=avg(res.map(r=>r.resolution_sla_met_or_not_yet_breached?1:0)),med=quantile(res.map(r=>+r.resolution_hours),.5),p90=quantile(res.map(r=>+r.resolution_hours),.9),over=open.filter(r=>+r.observed_elapsed_hours>+r.sla_target_hours).length, handrate=pct(all.map(r=>+r.handoffs>0)), reopens=pct(all.map(r=>+r.reopened_count>0));
$('filterNote').textContent=`${fmtNum(all.length)} requests in view · ${fmtNum(res.length)} resolved · ${fmtNum(open.length)} still open · snapshot ${DATA.as_of}.`;
let kpis=[['Requests in view',fmtNum(all.length),'After the filters'],['Resolved within target',fmtPct(sla),'Resolved requests only'],['Open and past target',fmtNum(over),'Needs an owner and next step'],['Median resolution',fmtH(med),'The typical resolved request'],['90th percentile',fmtH(p90),'The slowest one in ten']];$('kpis').innerHTML=kpis.map(k=>`<div class="kpi"><span>${k[0]}</span><strong>${k[1]}</strong><small>${k[2]}</small></div>`).join('');
const bymonth=group(all,r=>r.created_at.slice(0,7));let months=Object.keys(bymonth).sort();let arrivals=months.map(m=>bymonth[m].length),resolvedByMonth=months.map(m=>bymonth[m].filter(r=>r.status==='Resolved'&&r.resolved_at&&r.resolved_at.slice(0,7)===m).length);chart('flowChart','line',months,[{label:'Arrivals',data:arrivals},{label:'Resolved in same month',data:resolvedByMonth}],{plugins:{legend:{display:true,position:'bottom'}}});
let gs=group(all,'service_type'),svcs=Object.keys(gs).sort((a,b)=>pct(gs[b].map(r=>r.sla_breached_or_at_risk))-pct(gs[a].map(r=>r.sla_breached_or_at_risk)));chart('riskChart','bar',svcs.map(x=>x.replace(' and ',' & ')),[{label:'Breached or at risk',data:svcs.map(s=>pct(gs[s].map(r=>r.sla_breached_or_at_risk))*100),backgroundColor:'#c46d53'}],{indexAxis:'y',plugins:{legend:{display:false}},scales:{x:{beginAtZero:true,max:100,ticks:{callback:v=>v+'%'}},y:{grid:{display:false}}}});
$('promiseInsight').innerHTML=`<b>What stands out:</b> the median resolved request took ${fmtH(med)}, while the 90th percentile took ${fmtH(p90)}. ${open.length?`${fmtNum(over)} open requests have already crossed their target.`:'No open requests in this filtered view have crossed their target.'} That gap is why a single average or backlog total is not enough.`;
let sv=svcs.map(s=>({s,rows:gs[s]}));chart('tailChart','bar',sv.map(x=>x.s),[{label:'Median hours',data:sv.map(x=>quantile(x.rows.filter(r=>r.status==='Resolved').map(r=>+r.resolution_hours),.5))},{label:'90th percentile hours',data:sv.map(x=>quantile(x.rows.filter(r=>r.status==='Resolved').map(r=>+r.resolution_hours),.9))}],{indexAxis:'y',plugins:{legend:{display:true,position:'bottom'}}});
let gh=group(res,'handoffs'),hkeys=Object.keys(gh).map(Number).sort((a,b)=>a-b);chart('handoffChart','line',hkeys.map(x=>String(x)),[{label:'Median resolution hours',data:hkeys.map(h=>quantile(gh[h].map(r=>+r.resolution_hours),.5))},{label:'90th percentile hours',data:hkeys.map(h=>quantile(gh[h].map(r=>+r.resolution_hours),.9))}],{plugins:{legend:{display:true,position:'bottom'}},scales:{x:{title:{display:true,text:'Number of handoffs'},grid:{display:false}},y:{title:{display:true,text:'Hours'}}}});
// Mix-adjusted expectation is recalculated in the filtered slice using service type + priority strata.
let strata=group(all,r=>r.priority+'|'+r.service_type),sr={};Object.keys(strata).forEach(k=>sr[k]=pct(strata[k].map(r=>r.sla_breached_or_at_risk)));let gt=group(all,'team'),tn=Object.keys(gt);let gaps=tn.map(t=>{let rows=gt[t],obs=pct(rows.map(r=>r.sla_breached_or_at_risk)),ex=avg(rows.map(r=>sr[r.priority+'|'+r.service_type]??obs));return {t,gap:100*(obs-ex),n:rows.length}}).sort((a,b)=>b.gap-a.gap);chart('teamChart','bar',gaps.map(x=>x.t),[{label:'Observed minus expected risk (pp)',data:gaps.map(x=>x.gap),backgroundColor:gaps.map(x=>x.gap>0?'#c46d53':'#167c80')}],{indexAxis:'y',plugins:{legend:{display:false}},scales:{x:{title:{display:true,text:'Percentage points'}},y:{grid:{display:false}}}});
const ps=['P1 - urgent','P2 - high','P3 - standard','P4 - low'];let htm='<thead><tr><th>Request type</th>'+ps.map(p=>`<th>${p.replace(' - ','<br>')}</th>`).join('')+'</tr></thead><tbody>';svcs.forEach(s=>{htm+=`<tr><td>${esc(s)}</td>`+ps.map(p=>{let rr=all.filter(r=>r.service_type===s&&r.priority===p);let v=pct(rr.map(r=>r.sla_breached_or_at_risk));return `<td><span class="pill ${v<.3?'ok':''}">${rr.length?fmtPct(v):'—'}</span></td>`}).join('')+'</tr>'});$('heatTable').innerHTML=htm+'</tbody>';
$('stallsInsight').innerHTML=`<b>What to inspect:</b> ${svcs[0]||'No service type'} has the highest observed at-risk share in this view. Handoffs and case mix travel together, so use the charts to choose requests for a closer look, not to assign blame. The team chart compares observed risk with the risk expected from that team’s current service and priority mix.`;
renderQueue(all);renderScenario(res,all);$('nextInsight').innerHTML=`<b>For the next shift:</b> review open requests already past target first, then check long-running cases with two or more handoffs. A small ownership or intake-rule change is easier to evaluate than a broad instruction to “work faster.” Record the change and compare p90 resolution time and SLA results over a defined period.`;
}
function renderQueue(rows){let s=$('queueSearch').value.toLowerCase();let q=rows.filter(r=>[r.request_id,r.team,r.service_type,r.priority].join(' ').toLowerCase().includes(s)).sort((a,b)=>+b.queue_attention_score- +a.queue_attention_score).slice(0,80);$('queueTable').querySelector('tbody').innerHTML=q.length?q.map(r=>`<tr><td>${esc(r.request_id)}</td><td>${r.status==='Open'?'<span class="pill">Open</span>':'<span class="pill ok">Resolved</span>'}</td><td>${esc(r.priority)}</td><td>${esc(r.service_type)}</td><td>${esc(r.team)}</td><td>${fmtH(+r.observed_elapsed_hours)}</td><td>${fmtH(+r.sla_target_hours)}</td><td class="score">${(+r.queue_attention_score).toFixed(1)}</td></tr>`).join(''):'<tr><td colspan="8" class="empty">No requests match the search.</td></tr>'}
function renderScenario(res,all){let base=quantile(res.map(r=>+r.resolution_hours),.9);let hand=+$('handoffSlider').value/100,cap=+$('capacitySlider').value/100;let avgH=avg(all.map(r=>+r.handoffs));let adjusted=base*Math.exp(-.23*avgH*hand)/(1+cap);let gain=Math.max(0,base-adjusted);$('handoffPct').textContent=Math.round(hand*100)+'%';$('capacityPct').textContent=Math.round(cap*100)+'%';$('scenarioHours').textContent=fmtH(adjusted);$('scenarioDelta').textContent=`About ${fmtH(gain)} below the current ${fmtH(base)} p90`}
document.querySelectorAll('.story-nav button').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('.story-nav button').forEach(x=>x.classList.toggle('active',x===b));document.querySelectorAll('.chapter').forEach(x=>x.classList.toggle('active',x.id===b.dataset.chapter));if(window.Chart)Object.values(charts).forEach(c=>c.resize())}));['service','team','priority','channel','from','to'].forEach(id=>$(id).addEventListener('change',update));$('queueSearch').addEventListener('input',()=>renderQueue(currentRows));['handoffSlider','capacitySlider'].forEach(id=>$(id).addEventListener('input',()=>renderScenario(currentRows.filter(r=>r.status==='Resolved'),currentRows)));
update();if(!window.Chart){document.querySelectorAll('.chartbox').forEach(el=>el.innerHTML='<p class="empty">The charts need an internet connection to load. The filtered numbers and table are still available.</p>')}
</script></body></html>'''
(ROOT/'index.html').write_text(template.replace('__DATA__',json.dumps(data,separators=(',',':'))))
print('dashboard bytes', (ROOT/'index.html').stat().st_size)
